/**
 * The group label for a page slug, e.g. `guides/sessions` -> `Guides`.
 * Returns undefined for pages outside the sidebar, such as the landing page.
 *
 * @param {string} slug
 * @returns {string | undefined}
 */
export function sectionForSlug(slug) {
	for (const group of sidebar) {
		if (!('items' in group) || !group.items) continue;
		for (const item of group.items) {
			if (typeof item === 'object' && 'slug' in item && item.slug === slug) return group.label;
		}
	}
	return undefined;
}
